--
-- Table structure for table `detected_events`
--

DROP TABLE IF EXISTS `detected_events`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `detected_events` (
  `event_id` bigint NOT NULL AUTO_INCREMENT,
  `patrol_id` bigint DEFAULT NULL,
  `robot_id` bigint NOT NULL,
  `event_type` varchar(30) NOT NULL,
  `event_title` varchar(200) NOT NULL,
  `event_details` text,
  `confidence` decimal(4,3) DEFAULT NULL,
  `occurred_at` timestamp(6) NOT NULL,
  `x_coordinate` decimal(10,3) DEFAULT NULL,
  `y_coordinate` decimal(10,3) DEFAULT NULL,
  `risk_level` varchar(20) NOT NULL,
  `processing_status` varchar(20) NOT NULL DEFAULT 'DETECTED',
  `processed_at` timestamp(6) NULL DEFAULT NULL,
  `recognized_license_plate` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`event_id`),
  KEY `idx_detected_events_patrol_id` (`patrol_id`),
  KEY `idx_detected_events_robot_id` (`robot_id`),
  KEY `idx_detected_events_status_occurred_at` (`processing_status`,`occurred_at`),
  CONSTRAINT `fk_detected_events_patrol` FOREIGN KEY (`patrol_id`) REFERENCES `patrols` (`patrol_id`),
  CONSTRAINT `fk_detected_events_robot` FOREIGN KEY (`robot_id`) REFERENCES `patrol_robots` (`robot_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1851 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

