DROP TABLE IF EXISTS `event_evidence`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `event_evidence` (
  `evidence_id` bigint NOT NULL AUTO_INCREMENT,
  `event_id` bigint NOT NULL,
  `media_type` varchar(20) NOT NULL,
  `file_url` varchar(1000) NOT NULL,
  `captured_at` timestamp(6) NULL DEFAULT NULL,
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`evidence_id`),
  KEY `idx_event_evidence_event_id` (`event_id`),
  CONSTRAINT `fk_event_evidence_event` FOREIGN KEY (`event_id`) REFERENCES `detected_events` (`event_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1845 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
