--
-- Table structure for table `event_processing_history`
--

DROP TABLE IF EXISTS `event_processing_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `event_processing_history` (
  `processing_history_id` bigint NOT NULL AUTO_INCREMENT,
  `event_id` bigint NOT NULL,
  `processing_member_id` bigint DEFAULT NULL,
  `changed_processing_status` varchar(20) NOT NULL,
  `processing_note` varchar(500) DEFAULT NULL,
  `changed_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`processing_history_id`),
  KEY `idx_event_processing_history_event_changed_at` (`event_id`,`changed_at`),
  KEY `idx_event_processing_history_member_id` (`processing_member_id`),
  CONSTRAINT `fk_event_processing_history_event` FOREIGN KEY (`event_id`) REFERENCES `detected_events` (`event_id`),
  CONSTRAINT `fk_event_processing_history_member` FOREIGN KEY (`processing_member_id`) REFERENCES `members` (`member_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3356 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

