DROP TABLE IF EXISTS `patrol_maps`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `patrol_maps` (
  `map_id` bigint NOT NULL AUTO_INCREMENT,
  `apartment_complex_id` bigint NOT NULL,
  `map_name` varchar(255) NOT NULL,
  `map_url` varchar(1000) NOT NULL,
  `resolution` decimal(6,4) DEFAULT NULL,
  `origin_x` decimal(10,3) DEFAULT NULL,
  `origin_y` decimal(10,3) DEFAULT NULL,
  `origin_yaw` decimal(6,2) DEFAULT NULL,
  `width` int DEFAULT NULL,
  `height` int DEFAULT NULL,
  `map_version` int DEFAULT '1',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`map_id`),
  UNIQUE KEY `uk_patrol_maps_apartment_complex` (`apartment_complex_id`),
  KEY `idx_patrol_maps_apartment_complex_id` (`apartment_complex_id`),
  CONSTRAINT `fk_patrol_maps_apartment_complex` FOREIGN KEY (`apartment_complex_id`) REFERENCES `apartment_complexes` (`apartment_complex_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
