  `camera_status` varchar(20) DEFAULT NULL,
  `lidar_status` varchar(20) DEFAULT NULL,
  `motor_status` varchar(20) DEFAULT NULL,
  `line_sensor_status` varchar(20) DEFAULT NULL,
