DROP TABLE IF EXISTS `patrols`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `patrols` (
  `patrol_id` bigint NOT NULL AUTO_INCREMENT,
  `robot_id` bigint NOT NULL,
  `command_id` varchar(36) DEFAULT NULL,
  `patrol_status` varchar(20) NOT NULL DEFAULT 'IN_PROGRESS',
  `patrol_started_at` timestamp(6) NULL DEFAULT NULL,
  `patrol_ended_at` timestamp(6) NULL DEFAULT NULL,
  `total_duration` int DEFAULT NULL,
  `detected_event_count` int NOT NULL DEFAULT '0',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `start_battery_level` decimal(5,2) DEFAULT NULL,
  `end_battery_level` decimal(5,2) DEFAULT NULL,
  `completion_requested` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`patrol_id`),
  UNIQUE KEY `uk_patrols_command_id` (`command_id`),
  KEY `idx_patrols_robot_id` (`robot_id`),
  KEY `idx_patrols_status_started_at` (`patrol_status`,`patrol_started_at`),
  CONSTRAINT `fk_patrols_robot` FOREIGN KEY (`robot_id`) REFERENCES `patrol_robots` (`robot_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1497 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
